const data = require('fs').readFileSync(0, 'utf8').trim().split(/\s+/);
let idx = 0;
const n = BigInt(data[idx++]);
const m = BigInt(data[idx++]);
const mod = 1000000007n;

function multiply(one, two, size) {
    const res = [];
    for (let i = 0; i < size; i++) {
        res.push(new Array(size).fill(0n));
    }
    for (let i = 0; i < size; i++) {
        for (let j = 0; j < size; j++) {
            let sum = 0n;
            for (let k = 0; k < size; k++) {
                sum += (one[i][k] * two[k][j]) % mod;
            }
            res[i][j] = sum % mod;
        }
    }
    return res;
}

function power(exp, base, size) {
    if (exp === 1n) {
        return base;
    }
    let res = power(exp / 2n, base, size);
    res = multiply(res, res, size);
    if ((exp & 1n) === 1n) {
        res = multiply(res, base, size);
    }
    return res;
}

function main() {
    if (n < m) {
        process.stdout.write("1");
        return;
    }
    if (n === m) {
        process.stdout.write("2");
        return;
    }

    const size = Number(m);
    const matrix = [];
    for (let i = 0; i < size; i++) {
        matrix.push(new Array(size).fill(0n));
    }
    matrix[0][0] = 1n;
    matrix[0][size - 1] = 1n;
    for (let i = 1; i < size; i++) {
        matrix[i][i - 1] = 1n;
    }

    const result = power(n, matrix, size);
    console.log(result[0][0].toString());
}

main();
